#ifndef WORDS_BIGENDIAN
/* LITTLE_ENDIAN: DEC and intel */
/*
 * Routines to convert to BIGENDIAN.
 * Optimize the swapn?b() and swap?b() routines aggressivly.
 */

#define SWAP2(a) ((((a) & 0xff) << 8) | (((a) >> 8) & 0xff))

#define SWAP4(a)                                                               \
  (((a) << 24) | (((a) << 8) & 0x00ff0000) | (((a) >> 8) & 0x0000ff00) |       \
   (((a) >> 24) & 0x000000ff))

static void swapn2b(void *dst, const void *src, size_t nn) {
  char *op = dst;
  const char *ip = src;

  /* unroll the following to reduce loop overhead
   *
   *	while(nn-- != 0)
   *	{
   *		*op++ = *(++ip);
   *		*op++ = *(ip++ -1);
   *	}
   */
  while (nn > 3) {
    *op++ = *(++ip);
    *op++ = *(ip++ - 1);
    *op++ = *(++ip);
    *op++ = *(ip++ - 1);
    *op++ = *(++ip);
    *op++ = *(ip++ - 1);
    *op++ = *(++ip);
    *op++ = *(ip++ - 1);
    nn -= 4;
  }
  while (nn-- != 0) {
    *op++ = *(++ip);
    *op++ = *(ip++ - 1);
  }
}

static void swap4b(void *dst, const void *src) {
  char *op = dst;
  const char *ip = src;
  op[0] = ip[3];
  op[1] = ip[2];
  op[2] = ip[1];
  op[3] = ip[0];
}

static void swapn4b(void *dst, const void *src, size_t nn) {
  char *op = dst;
  const char *ip = src;

  /* unroll the following to reduce loop overhead
   *	while(nn-- != 0)
   *	{
   *		op[0] = ip[3];
   *		op[1] = ip[2];
   *		op[2] = ip[1];
   *		op[3] = ip[0];
   *		op += 4;
   *		ip += 4;
   *	}
   */
  while (nn > 3) {
    op[0] = ip[3];
    op[1] = ip[2];
    op[2] = ip[1];
    op[3] = ip[0];
    op[4] = ip[7];
    op[5] = ip[6];
    op[6] = ip[5];
    op[7] = ip[4];
    op[8] = ip[11];
    op[9] = ip[10];
    op[10] = ip[9];
    op[11] = ip[8];
    op[12] = ip[15];
    op[13] = ip[14];
    op[14] = ip[13];
    op[15] = ip[12];
    op += 16;
    ip += 16;
    nn -= 4;
  }
  while (nn-- != 0) {
    op[0] = ip[3];
    op[1] = ip[2];
    op[2] = ip[1];
    op[3] = ip[0];
    op += 4;
    ip += 4;
  }
}

static void swap8b(void *dst, const void *src) {
  char *op = dst;
  const char *ip = src;
#ifndef FLOAT_WORDS_BIGENDIAN
  op[0] = ip[7];
  op[1] = ip[6];
  op[2] = ip[5];
  op[3] = ip[4];
  op[4] = ip[3];
  op[5] = ip[2];
  op[6] = ip[1];
  op[7] = ip[0];
#else
  op[0] = ip[3];
  op[1] = ip[2];
  op[2] = ip[1];
  op[3] = ip[0];
  op[4] = ip[7];
  op[5] = ip[6];
  op[6] = ip[5];
  op[7] = ip[4];
#endif
}

static void swapn8b(void *dst, const void *src, size_t nn) {
  char *op = dst;
  const char *ip = src;

/* unroll the following to reduce loop overhead
 *	while(nn-- != 0)
 *	{
 *		op[0] = ip[7];
 *		op[1] = ip[6];
 *		op[2] = ip[5];
 *		op[3] = ip[4];
 *		op[4] = ip[3];
 *		op[5] = ip[2];
 *		op[6] = ip[1];
 *		op[7] = ip[0];
 *		op += 8;
 *		ip += 8;
 *	}
 */
#ifndef FLOAT_WORDS_BIGENDIAN
  while (nn > 1) {
    op[0] = ip[7];
    op[1] = ip[6];
    op[2] = ip[5];
    op[3] = ip[4];
    op[4] = ip[3];
    op[5] = ip[2];
    op[6] = ip[1];
    op[7] = ip[0];
    op[8] = ip[15];
    op[9] = ip[14];
    op[10] = ip[13];
    op[11] = ip[12];
    op[12] = ip[11];
    op[13] = ip[10];
    op[14] = ip[9];
    op[15] = ip[8];
    op += 16;
    ip += 16;
    nn -= 2;
  }
  while (nn-- != 0) {
    op[0] = ip[7];
    op[1] = ip[6];
    op[2] = ip[5];
    op[3] = ip[4];
    op[4] = ip[3];
    op[5] = ip[2];
    op[6] = ip[1];
    op[7] = ip[0];
    op += 8;
    ip += 8;
  }
#else
  while (nn-- != 0) {
    op[0] = ip[3];
    op[1] = ip[2];
    op[2] = ip[1];
    op[3] = ip[0];
    op[4] = ip[7];
    op[5] = ip[6];
    op[6] = ip[5];
    op[7] = ip[4];
    op += 8;
    ip += 8;
  }
#endif
}

#endif /* LITTLE_ENDIAN */

