int ncx_put_int_schar(void *xp, const schar *ip) {
  uchar *cp = (uchar *)xp;
  if (*ip & 0x80) {
    *cp++ = 0xff;
    *cp++ = 0xff;
    *cp++ = 0xff;
  } else {
    *cp++ = 0x00;
    *cp++ = 0x00;
    *cp++ = 0x00;
  }
  *cp = (uchar)*ip;
  return ENOERR;
}

int ncx_put_int_uchar(void *xp, const uchar *ip) {
  uchar *cp = (uchar *)xp;
  *cp++ = 0x00;
  *cp++ = 0x00;
  *cp++ = 0x00;
  *cp = *ip;
  return ENOERR;
}

