static void get_ix_float(const void *xp, float *ip) {
#ifdef WORDS_BIGENDIAN
  (void)memcpy(ip, xp, sizeof(float));
#else
  swap4b(ip, xp);
#endif
}

static void put_ix_float(void *xp, const float *ip) {
#ifdef WORDS_BIGENDIAN
  (void)memcpy(xp, ip, X_SIZEOF_FLOAT);
#else
  swap4b(xp, ip);
#endif
}

