/* x_size_t */

#if SIZEOF_SIZE_T < X_SIZEOF_SIZE_T
#error "x_size_t implementation"
/* netcdf requires size_t which can hold a values from 0 to 2^32 -1 */
#endif

int ncx_put_size_t(void **xpp, const size_t *ulp) {
  /* similar to put_ix_int() */
  uchar *cp = (uchar *)*xpp;
  assert(*ulp <= X_SIZE_MAX);

  *cp++ = (uchar)((*ulp) >> 24);
  *cp++ = (uchar)(((*ulp) & 0x00ff0000) >> 16);
  *cp++ = (uchar)(((*ulp) & 0x0000ff00) >> 8);
  *cp = (uchar)((*ulp) & 0x000000ff);

  *xpp = (void *)((char *)(*xpp) + X_SIZEOF_SIZE_T);
  return ENOERR;
}

int ncx_get_size_t(const void **xpp, size_t *ulp) {
  /* similar to get_ix_int */
  const uchar *cp = (const uchar *)*xpp;

  *ulp = (unsigned)(*cp++ << 24);
  *ulp |= (*cp++ << 16);
  *ulp |= (*cp++ << 8);
  *ulp |= *cp;

  *xpp = (const void *)((const char *)(*xpp) + X_SIZEOF_SIZE_T);
  return ENOERR;
}

/* x_off_t */

int ncx_put_off_t(void **xpp, const off_t *lp, size_t sizeof_off_t) {
  /* similar to put_ix_int() */
  uchar *cp = (uchar *)*xpp;
  /* No negative offsets stored in netcdf */
  if (*lp < 0) {
    /* Assume this is an overflow of a 32-bit int... */
    return ERANGE;
  }

  assert(sizeof_off_t == 4 || sizeof_off_t == 8);

  if (sizeof_off_t == 4) {
    *cp++ = (uchar)((*lp) >> 24);
    *cp++ = (uchar)(((*lp) & 0x00ff0000) >> 16);
    *cp++ = (uchar)(((*lp) & 0x0000ff00) >> 8);
    *cp = (uchar)((*lp) & 0x000000ff);
  } else {
#if SIZEOF_OFF_T == 4
    /* Write a 64-bit offset on a system with only a 32-bit offset */
    *cp++ = (uchar)0;
    *cp++ = (uchar)0;
    *cp++ = (uchar)0;
    *cp++ = (uchar)0;

    *cp++ = (uchar)(((*lp) & 0xff000000) >> 24);
    *cp++ = (uchar)(((*lp) & 0x00ff0000) >> 16);
    *cp++ = (uchar)(((*lp) & 0x0000ff00) >> 8);
    *cp = (uchar)((*lp) & 0x000000ff);
#else
    *cp++ = (uchar)((*lp) >> 56);
    *cp++ = (uchar)(((*lp) & 0x00ff000000000000ULL) >> 48);
    *cp++ = (uchar)(((*lp) & 0x0000ff0000000000ULL) >> 40);
    *cp++ = (uchar)(((*lp) & 0x000000ff00000000ULL) >> 32);
    *cp++ = (uchar)(((*lp) & 0x00000000ff000000ULL) >> 24);
    *cp++ = (uchar)(((*lp) & 0x0000000000ff0000ULL) >> 16);
    *cp++ = (uchar)(((*lp) & 0x000000000000ff00ULL) >> 8);
    *cp = (uchar)((*lp) & 0x00000000000000ffULL);
#endif
  }
  *xpp = (void *)((char *)(*xpp) + sizeof_off_t);
  return ENOERR;
}

int ncx_get_off_t(const void **xpp, off_t *lp, size_t sizeof_off_t) {
  /* similar to get_ix_int() */
  const uchar *cp = (const uchar *)*xpp;
  assert(sizeof_off_t == 4 || sizeof_off_t == 8);

  if (sizeof_off_t == 4) {
    *lp = *cp++ << 24;
    *lp |= (*cp++ << 16);
    *lp |= (*cp++ << 8);
    *lp |= *cp;
  } else {
#if SIZEOF_OFF_T == 4
    /* Read a 64-bit offset on a system with only a 32-bit offset */
    /* If the offset overflows, set an error code and return */
    *lp = ((off_t)(*cp++) << 24);
    *lp |= ((off_t)(*cp++) << 16);
    *lp |= ((off_t)(*cp++) << 8);
    *lp |= ((off_t)(*cp++));
    /*
     * lp now contains the upper 32-bits of the 64-bit offset.  if lp is
     * not zero, then the dataset is larger than can be represented
     * on this system.  Set an error code and return.
     */
    if (*lp != 0) {
      return ERANGE;
    }

    *lp = ((off_t)(*cp++) << 24);
    *lp |= ((off_t)(*cp++) << 16);
    *lp |= ((off_t)(*cp++) << 8);
    *lp |= (off_t)*cp;

    if (*lp < 0) {
      /*
       * If this fails, then the offset is >2^31, but less
       * than 2^32 which is not allowed, but is not caught
       * by the previous check
       */
      return ERANGE;
    }
#else
    *lp = ((off_t)(*cp++) << 56);
    *lp |= ((off_t)(*cp++) << 48);
    *lp |= ((off_t)(*cp++) << 40);
    *lp |= ((off_t)(*cp++) << 32);
    *lp |= ((off_t)(*cp++) << 24);
    *lp |= ((off_t)(*cp++) << 16);
    *lp |= ((off_t)(*cp++) << 8);
    *lp |= (off_t)*cp;
#endif
  }
  *xpp = (const void *)((const char *)(*xpp) + sizeof_off_t);
  return ENOERR;
}

