int ncx_pad_putn_short_schar(void **xpp, size_t nelems, const schar *tp) {
  const size_t rndup = nelems % 2;

  char *xp = (char *)*xpp;
  int status = ENOERR;

  for (; nelems != 0; nelems--, xp += X_SIZEOF_SHORT, tp++) {
    int lstatus = ncx_put_short_schar(xp, tp);
    if (lstatus != ENOERR)
      status = lstatus;
  }

  if (rndup != 0) {
    (void)memcpy(xp, nada, X_SIZEOF_SHORT);
    xp += X_SIZEOF_SHORT;
  }

  *xpp = (void *)xp;
  return status;
}

