#if X_SIZEOF_DOUBLE == SIZEOF_DOUBLE && !defined(NO_IEEE_FLOAT)
/* optimized version */
int ncx_putn_double_double(void **xpp, size_t nelems, const double *tp) {
#ifdef WORDS_BIGENDIAN
  (void)memcpy(*xpp, tp, nelems * X_SIZEOF_DOUBLE);
#else
  swapn8b(*xpp, tp, nelems);
#endif
  *xpp = (void *)((char *)(*xpp) + nelems * X_SIZEOF_DOUBLE);
  return ENOERR;
}
#else
int ncx_putn_double_double(void **xpp, size_t nelems, const double *tp) {
  char *xp = *xpp;
  int status = ENOERR;

  for (; nelems != 0; nelems--, xp += X_SIZEOF_DOUBLE, tp++) {
    int lstatus = ncx_put_double_double(xp, tp);
    if (lstatus != ENOERR)
      status = lstatus;
  }

  *xpp = (void *)xp;
  return status;
}

#endif

/*
 * Other aggregate conversion functions.
 */

/* text */

int ncx_getn_text(const void **xpp, size_t nelems, char *tp) {
  (void)memcpy(tp, *xpp, nelems);
  *xpp = (void *)((char *)(*xpp) + nelems);
  return ENOERR;
}

int ncx_pad_getn_text(const void **xpp, size_t nelems, char *tp) {
  size_t rndup = nelems % X_ALIGN;

  if (rndup)
    rndup = X_ALIGN - rndup;

  (void)memcpy(tp, *xpp, nelems);
  *xpp = (void *)((char *)(*xpp) + nelems + rndup);

  return ENOERR;
}

int ncx_putn_text(void **xpp, size_t nelems, const char *tp) {
  (void)memcpy(*xpp, tp, nelems);
  *xpp = (void *)((char *)(*xpp) + nelems);

  return ENOERR;
}

int ncx_pad_putn_text(void **xpp, size_t nelems, const char *tp) {
  size_t rndup = nelems % X_ALIGN;

  if (rndup)
    rndup = X_ALIGN - rndup;

  (void)memcpy(*xpp, tp, nelems);
  *xpp = (void *)((char *)(*xpp) + nelems);

  if (rndup) {
    (void)memcpy(*xpp, nada, rndup);
    *xpp = (void *)((char *)(*xpp) + rndup);
  }

  return ENOERR;
}

